import {bindProfilePhoto,profilePhotoPicker} from './profile-photo-picker.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showUserSettings(user,{modal,close,toast,onSave,logout}){modal(`<div class="eyebrow">ACCOUNT SETTINGS</div><h2>Cài đặt người dùng</h2><form id="user-settings-form">${profilePhotoPicker()}<label for="settings-name">${user.accountType==='nickname'?'Thay đổi biệt danh':'Thay đổi tên'}</label><input id="settings-name" name="name" required minlength="${user.accountType==='nickname'?3:2}" maxlength="${user.accountType==='nickname'?30:100}" value="${esc(user.name)}"><label for="settings-address">Thay đổi địa chỉ / khu vực</label><input id="settings-address" name="address" maxlength="200" autocomplete="street-address" value="${esc(user.address||'')}"><label for="settings-email">Thay đổi email</label><input id="settings-email" name="emailPending" type="email" maxlength="254" autocomplete="email" value="${esc(user.emailPending||user.email||'')}" placeholder="ban@example.com"><p class="settings-email-note">${user.email?`Email đăng nhập hiện tại: <strong>${esc(user.email)}</strong>.<br>`:''}Email mới chỉ lưu dưới dạng yêu cầu chờ xác minh; chưa thay đổi email đăng nhập. Dịch vụ xác minh email đang được chuẩn bị.</p><label for="settings-phone">Thay đổi số điện thoại</label><input id="settings-phone" name="phone" type="tel" maxlength="25" autocomplete="tel" value="${esc(user.phone||'')}" placeholder="+84 912 345 678">${user.designPreview?'<p class="settings-email-note">Chế độ xây dựng: các thay đổi chỉ lưu trên trình duyệt.</p>':''}<p id="settings-error" class="form-error" role="alert"></p><button class="dark">Lưu thay đổi</button><button type="button" id="settings-logout" class="settings-logout">↪ Đăng xuất</button></form>`);
document.querySelector('#settings-logout').onclick=()=>{document.body.classList.remove('broke-mode');close();logout();};
const form=document.querySelector('#user-settings-form');
const readPhoto=bindProfilePhoto(form,user.photo,user.name?.charAt(0)||'♡');
form.onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('.dark');button.disabled=true;const data={...Object.fromEntries(new FormData(event.target)),photo:await readPhoto()};try{let updated;if(user.designPreview){if(data.phone&&!/^\+?[\d\s().-]{8,25}$/.test(data.phone))throw Error('Vui lòng kiểm tra số điện thoại.');updated={...user,...data};localStorage.setItem('debtfreelately-preview-settings',JSON.stringify(data));}else{const response=await fetch('/api/auth/profile',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Không lưu được cài đặt.');updated=result.user;}onSave(updated);close();toast(data.emailPending&&data.emailPending!==user.email?'Đã lưu thông tin. Email mới đang chờ xác minh.':'Đã lưu cài đặt người dùng.');}catch(error){document.querySelector('#settings-error').textContent=error.message;button.disabled=false;}};
}

